def is_valid_bst(root):
    prev = -float('inf')
    def dfs(n):
        nonlocal prev
        if not n: return True
        if not dfs(n.left): return False
        if n.val <= prev: return False
        prev = n.val
        return dfs(n.right)
    return dfs(root)

def kth_smallest(root, k):
    st = []; cur = root
    while True:
        while cur:
            st.append(cur); cur = cur.left
        cur = st.pop(); k -= 1
        if k == 0: return cur.val
        cur = cur.right

def delete_node(root, key):
    if not root: return None
    if key < root.val:
        root.left = delete_node(root.left, key)
    elif key > root.val:
        root.right = delete_node(root.right, key)
    else:
        if not root.left or not root.right:
            return root.left or root.right
        pred = root.left
        while pred.right: pred = pred.right
        root.val = pred.val
        root.left = delete_node(root.left, pred.val)
    return root

def get_minimum_difference(root):
    vals = []
    def dfs(n):
        if not n: return
        dfs(n.left); vals.append(n.val); dfs(n.right)
    dfs(root)
    return min(vals[i+1] - vals[i] for i in range(len(vals) - 1))

def find_target(root, k):
    seen = set()
    st = [root]
    while st:
        n = st.pop()
        if k - n.val in seen: return True
        seen.add(n.val)
        if n.left: st.append(n.left)
        if n.right: st.append(n.right)
    return False

def search_bst(root, val):
    cur = root
    while cur and cur.val != val:
        cur = cur.left if val < cur.val else cur.right
    return cur

def search_bst(root, val):
    if not root: return None
    if root.val == val: return root
    if val < root.val: return search_bst(root.left, val)
    return search_bst(root.right, val)

